# ── Helper: draw text with optional anchor ───────────────────
def draw_text(draw, xy, text, font, fill, anchor=None, align="left"):
    """Draw text at xy. anchor can be 'lt','mt','rt','lm','mm','rm','lb','mb','rb'."""
    if anchor is None:
        draw.text(xy, text, font=font, fill=fill, align=align)
    elif "\n" in text:
        # PIL doesn't support anchor with multiline — compute manually
        bbox = draw.multiline_textbbox((0, 0), text, font=font, align=align)
        tw, th = bbox[2] - bbox[0], bbox[3] - bbox[1]
        x, y = xy
        if anchor[0] == "m":
            x -= tw // 2
        elif anchor[0] == "r":
            x -= tw
        if anchor[1] == "m":
            y -= th // 2
        elif anchor[1] == "b":
            y -= th
        draw.multiline_text((x, y), text, font=font, fill=fill, align=align)
    else:
        draw.text(xy, text, font=font, fill=fill, anchor=anchor, align=align)

